// spec: .qa/e2e/specs/post-create.md · seed: tests/seed.free.spec.ts · кейс .qa/tests/post-create/PC-04.md
// @data: идёт в проекте data; устройство — iPhone 13 Mini (WebKit) через test.use ниже.
import { test, expect } from '@playwright/test';
import { saveSession } from '../_shared/session';
import { IMG1, IMG2, IPHONE, authFile, cleanupPost, deletePostViaUi, form, isPostCreate, isUpload, openComposer, postCard, qaText, tap, type Published } from './post-helpers';

test.use({ ...IPHONE, storageState: authFile('free') });

test.describe('מסך יצירת פוסט', () => {
  test('Два фото → ✕ «הסרת התמונה» убирает одно → публикуется только оставшееся; затем удаление @iphone @data (#1ff0f4)', async ({ page }) => {
    test.setTimeout(120_000);
    const text = qaText('photo');
    let published: Published | undefined;
    let deleted = false;
    let uploads = 0;
    page.on('response', (r) => { if (isUpload(r)) uploads++; });
    try {
      // 1. Форма, текст
      await openComposer(page);
      const f = form(page);
      await f.text.fill(text);

      // 2. Добавить 2 фото (нейтральные картинки из .qa/tmp-upload)
      for (const [i, img] of [IMG1, IMG2].entries()) {
        const chooser = page.waitForEvent('filechooser');
        await tap(page, f.addPhoto);
        await (await chooser).setFiles(img);
        await expect(f.removePhoto).toHaveCount(i + 1);
      }
      await expect(f.addPhoto).toBeVisible();

      // 3. ✕ на первом фото
      await tap(page, f.removePhoto.first());
      await expect(f.removePhoto).toHaveCount(1);

      // 4. Публикация: фото грузится в storage при публикации; в запросе одно фото
      const reqP = page.waitForRequest(isPostCreate);
      const resP = page.waitForResponse((r) => isPostCreate(r.request()));
      await tap(page, f.publish);
      const req = await reqP;
      const data = req.postDataJSON();
      expect(data.body).toBe(text);
      expect(String(data.image_url ?? ''), 'image_url').toContain('/storage/v1/object/public/posts/');
      expect(data.extra_image_urls ?? [], 'extra_image_urls — удалённое фото не ушло').toHaveLength(0);
      const res = await resP;
      expect(res.status()).toBe(201);
      expect(uploads, 'в storage загружено только оставшееся фото').toBe(1);
      const body = await res.json();
      published = { id: String((Array.isArray(body) ? body[0] : body).id), text, rest: new URL(res.url()).origin, headers: await req.allHeaders() };
      await page.waitForURL(/\/social/);
      await expect(postCard(page, text).getByRole('img')).toHaveCount(1);

      // 5. Очистка
      await deletePostViaUi(page, text);
      deleted = true;
    } finally {
      if (published && !deleted) await cleanupPost(page, published);
      await saveSession(page, 'free');
    }
  });
});
